/**
 * T009f - emit evidence/runs/angular-13cell/pigallery2-live-witness-3.json.
 *
 * Every measured number in the record is READ OUT of the two lane JSONs the
 * witness driver wrote and the two build logs the rebuild wrote. Nothing
 * measured is typed by hand. The prose is the only hand-written part.
 */
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const REPO = '/Users/jacksm5pro/dev/open-source/versionless';
const W = path.join(REPO, '.versionless/work/angular-pigallery2');
const L = path.join(W, 'logs');
const CELL = path.join(W, '13cell');
const OUT = path.join(REPO, 'evidence/runs/angular-13cell/pigallery2-live-witness-3.json');

const readJson = (p) => JSON.parse(fs.readFileSync(p, 'utf8'));
const sha256File = (p) => crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
const rel = (p) => path.relative(REPO, p);

const baselineLane = readJson(path.join(L, 't009f-lane-baseline.json'));
const migratedLane = readJson(path.join(L, 't009f-lane-migrated.json'));
const buildCompare = readJson(path.join(L, 't009f-migrated-compare.json'));

/* ---------------------------------------------------------------- builds -- */
const buildRun = (n) => {
  const log = fs.readFileSync(path.join(CELL, 'logs', `t009f-migrated-run${n}.log`), 'utf8');
  const m = /Build at: (\S+) - Hash: (\S+) - Time: (\d+)ms/.exec(log);
  const ec = /EXIT=(\d+) WALL=(\d+)/.exec(log);
  return {
    run: n,
    outDir: rel(path.join(CELL, `t009f-migrated-run${n}`)),
    exitCode: Number(ec[1]),
    wallSeconds: Number(ec[2]),
    webpackHash: m[2],
    webpackTimeMs: Number(m[3]),
    builtAt: m[1],
    ngccRan: /Entry point '.*' contains deep imports/.test(log),
  };
};
const runs = [buildRun(1), buildRun(2)];

const inventory = (dir) => {
  const d = path.join(CELL, dir);
  return Object.fromEntries(
    fs.readdirSync(d)
      .filter((f) => fs.statSync(path.join(d, f)).isFile())
      .map((f) => [f.replace(/\.[0-9a-f]{16}\./, '.<hash>.'), { name: f, sha256: sha256File(path.join(d, f)), bytes: fs.statSync(path.join(d, f)).size }])
  );
};
const invE = inventory('t009e-migrated-run1');
const invF1 = inventory('t009f-migrated-run1');
const invF2 = inventory('t009f-migrated-run2');
const chunkDelta = Object.keys(invF1).map((k) => ({
  file: k,
  t009eName: invE[k] ? invE[k].name : null,
  t009fName: invF1[k].name,
  changed: !invE[k] || invE[k].sha256 !== invF1[k].sha256,
  t009eSha256: invE[k] ? invE[k].sha256 : null,
  t009fSha256: invF1[k].sha256,
}));
const changedFiles = chunkDelta.filter((c) => c.changed).map((c) => c.file);
const unchangedFiles = chunkDelta.filter((c) => !c.changed).map((c) => c.file);
const doubleBuildIdentical = Object.keys(invF1).every((k) => invF2[k] && invF2[k].sha256 === invF1[k].sha256);

/* -------------------------------------------------- application signals -- */
const API_RE = /\/api\//;
const signalsFor = (lane) => {
  const j = lane.journeys[0];
  const s = j.surface;
  const summary = /(\d+)\n(Images|Videos|Items)\n(\d+ items)/.exec(s.visibleText || '');
  return {
    bootstrapped: s.appRootPresent === true && s.appRootChildElementCount > 1,
    bootstrappedReadFrom: 'surface.appRootPresent && surface.appRootChildElementCount > 1, evaluated in the page by the witness driver after its two bounded waits.',
    routedTo: s.location,
    routedToReadFrom: 'location.pathname + location.search + location.hash, evaluated in the page after the journey.',
    apiCalls: lane.requestOutcomes
      .filter((r) => API_RE.test(r.url))
      .map((r) => ({ method: r.method, url: r.url, status: r.status })),
    apiCallsReadFrom: "the witness host's own requestOutcomes() network ledger, filtered to /api/. Not inferred from the DOM.",
    gallery: {
      tiles: s.photoTiles,
      tilesReadFrom: "document.querySelectorAll('app-gallery-grid-photo').length, evaluated in the page.",
      summaryText: summary ? summary[0] : null,
      summaryTextReadFrom: summary
        ? 'verbatim substring of surface.visibleText (document.body.innerText), matched by /(\\d+)\\n(Images|Videos|Items)\\n(\\d+ items)/. The newlines are the page\'s own line breaks; rendered it reads "3 Images / 3 items".'
        : 'no such substring was present in surface.visibleText.',
      componentPresent: s.galleryComponentPresent,
      gridPresent: s.gridPresent,
      navbarPresent: s.navbarPresent,
      photoImages: s.photoImages,
    },
